// === RENDER EMAIL HTML ===
// Missive's drafts.body is HTML, not markdown. Shipping raw markdown is why
// the brief arrived as a wall of literal ** and [text](url) with every line
// break collapsed — the same bug fixed in flow 2c on 2026-08-05.
//
// The markdown stays canonical (ClickUp, Drive, Obsidian and Athena's
// augmenter all read it). This node renders that one string into email-safe
// HTML at the last step before the send. Nothing else in the flow changes.
//
// Deliberately narrow: it handles exactly the constructs this brief emits —
// h1/h2/h3, bullets, blockquotes, tables, rules, bold/italic/code, links.
// No external library (n8n Code nodes have no npm), no layout tables, no
// background colours (they fight dark mode). Structure and spacing are
// inline-styled; body text colour is left to inherit so the mail client's
// own light/dark handling wins.

const src = $json;
const md = src.briefMarkdown || '';

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Inline spans, applied AFTER escaping so user text can never inject markup.
function inline(text) {
  let t = esc(text);
  t = t.replace(/`([^`]+)`/g,
    '<code style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:0.9em">$1</code>');
  // [label](url) -> anchor. Only http(s) targets become links; anything else
  // renders as plain text rather than a clickable unknown scheme.
  t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g,
    '<a href="$2" style="color:#2563eb;text-decoration:underline">$1</a>');
  t = t.replace(/\[\[[^\]|]*\|([^\]]+)\]\]/g, '$1');   // wikilinks -> plain text
  t = t.replace(/\[\[([^\]]+)\]\]/g, '$1');
  t = t.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/(^|[\s(])\*([^*\n]+)\*(?=[\s).,;:!?]|$)/g, '$1<em>$2</em>');
  t = t.replace(/(^|[\s(])_([^_\n]+)_(?=[\s).,;:!?]|$)/g, '$1<em>$2</em>');
  return t;
}

const H = {
  h1: 'margin:0 0 4px;font-size:22px;line-height:1.3;font-weight:700',
  h2: 'margin:28px 0 8px;font-size:16px;line-height:1.3;font-weight:700;text-transform:uppercase;letter-spacing:0.04em',
  h3: 'margin:18px 0 6px;font-size:14px;line-height:1.3;font-weight:700',
  p:  'margin:0 0 10px;font-size:15px;line-height:1.55',
  li: 'margin:0 0 6px;font-size:15px;line-height:1.5',
  ul: 'margin:0 0 12px;padding-left:20px',
  bq: 'margin:0 0 14px;padding:8px 14px;border-left:3px solid #c7cdd6;font-size:14px;line-height:1.5;color:#6b7280',
  hr: 'border:0;border-top:1px solid #e5e7eb;margin:22px 0',
  td: 'padding:6px 10px;border-bottom:1px solid #e5e7eb;font-size:14px;text-align:left;vertical-align:top',
};

const out = [];
const lines = md.split('\n');
let listOpen = false, quoteBuf = [], tableBuf = [];

function closeList() { if (listOpen) { out.push('</ul>'); listOpen = false; } }

function flushQuote() {
  if (!quoteBuf.length) return;
  out.push('<blockquote style="' + H.bq + '">' +
           quoteBuf.map(inline).join('<br>') + '</blockquote>');
  quoteBuf = [];
}

function flushTable() {
  if (!tableBuf.length) return;
  const rows = tableBuf
    .filter((r) => !/^\|[\s:|-]+\|$/.test(r.trim()))
    .map((r) => r.trim().replace(/^\|/, '').replace(/\|$/, '').split('|'));
  if (rows.length) {
    const head = rows.shift();
    out.push('<table style="border-collapse:collapse;width:100%;margin:0 0 14px">');
    out.push('<thead><tr>' + head.map((c) =>
      '<th style="' + H.td + ';font-weight:700">' + inline(c.trim()) + '</th>').join('') +
      '</tr></thead><tbody>');
    rows.forEach((r) => {
      out.push('<tr>' + r.map((c) =>
        '<td style="' + H.td + '">' + inline(c.trim()) + '</td>').join('') + '</tr>');
    });
    out.push('</tbody></table>');
  }
  tableBuf = [];
}

function flushBlocks() { flushQuote(); flushTable(); }

for (let i = 0; i < lines.length; i++) {
  const raw = lines[i];
  const line = raw.trim();

  if (line.indexOf('<!--') === 0) { continue; }            // marker comments
  if (line === '') { closeList(); flushBlocks(); continue; }

  if (line.charAt(0) === '|') { closeList(); flushQuote(); tableBuf.push(line); continue; }
  flushTable();

  if (line.charAt(0) === '>') {
    closeList();
    quoteBuf.push(line.replace(/^>\s?/, ''));
    continue;
  }
  flushQuote();

  if (/^-{3,}$/.test(line)) { closeList(); out.push('<hr style="' + H.hr + '">'); continue; }

  if (line.indexOf('### ') === 0) {
    closeList();
    out.push('<h3 style="' + H.h3 + '">' + inline(line.slice(4)) + '</h3>');
    continue;
  }
  if (line.indexOf('## ') === 0) {
    closeList();
    out.push('<h2 style="' + H.h2 + '">' + inline(line.slice(3)) + '</h2>');
    continue;
  }
  if (line.indexOf('# ') === 0) {
    closeList();
    out.push('<h1 style="' + H.h1 + '">' + inline(line.slice(2)) + '</h1>');
    continue;
  }

  if (/^[-*]\s+/.test(line)) {
    if (!listOpen) { out.push('<ul style="' + H.ul + '">'); listOpen = true; }
    // A '  \n' continuation under a bullet (attendees, agenda link) belongs to
    // the same <li>, indented and muted.
    let item = inline(line.replace(/^[-*]\s+/, ''));
    while (i + 1 < lines.length && /^\s{2,}\S/.test(lines[i + 1]) &&
           !/^\s*[-*]\s/.test(lines[i + 1])) {
      item += '<br><span style="color:#6b7280">' + inline(lines[++i].trim()) + '</span>';
    }
    out.push('<li style="' + H.li + '">' + item + '</li>');
    continue;
  }

  closeList();
  out.push('<p style="' + H.p + '">' + inline(line) + '</p>');
}
closeList();
flushBlocks();

// Footer: the artifact links, as real buttons-ish text rather than raw URLs.
const links = [];
if (src.clickupUrl) links.push('<a href="' + src.clickupUrl +
  '" style="color:#2563eb;text-decoration:underline">Open in ClickUp</a>');
if (src.gdriveUrl) links.push('<a href="' + src.gdriveUrl +
  '" style="color:#2563eb;text-decoration:underline">Google Doc</a>');
if (links.length) {
  out.push('<hr style="' + H.hr + '">');
  out.push('<p style="' + H.p + ';color:#6b7280">' + links.join(' &nbsp;·&nbsp; ') + '</p>');
}

const html =
  '<div style="max-width:680px;margin:0 auto;padding:4px 2px;' +
  'font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,Helvetica,Arial,sans-serif;' +
  '-webkit-text-size-adjust:100%">' + out.join('\n') + '</div>';

// Subject carries the load-bearing counts so the inbox row is useful unopened,
// but only the first three — a subject longer than ~78 chars is truncated by
// every mail client and the tail is wasted.
const glanceBits = (src.atAGlance || '').split(' · ').slice(0, 3).join(' · ');
const subject = 'Daily Brief — ' + src.dayOfWeek.slice(0, 3) + ' ' +
                (src.dateFormatted || '').replace(/,\s*\d{4}$/, '') +
                (glanceBits ? ' · ' + glanceBits : '');

return [{ json: Object.assign({}, src, { briefHtml: html, emailSubject: subject }) }];
